#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_OUTGOING FW_INCOMING_WAN_DMZ FW_OUTGOING_LANDMZ FW_1TO1_NAT FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_ALL_INTERNAL && fail 'an IP group named fws_ALL_INTERNAL exists; nothing was written'
named FW_GROUP_IP fws_SERVERS && fail 'an IP group named fws_SERVERS exists; nothing was written'
named FW_GROUP_PORT fws_WEB && fail 'a port group named fws_WEB exists; nothing was written'
named FW_GROUP_IP fws_WAN_to_Web_dst && fail 'an IP group named fws_WAN_to_Web_dst exists; nothing was written'
named FW_GROUP_IP fws_WAN_to_Mail_dst && fail 'an IP group named fws_WAN_to_Mail_dst exists; nothing was written'
named FW_GROUP_PORT fws_MGMT && fail 'a port group named fws_MGMT exists; nothing was written'
named FW_GROUP_IP fws_ADMIN_PCS && fail 'an IP group named fws_ADMIN_PCS exists; nothing was written'
named FW_GROUP_IP fws_PORTAL && fail 'an IP group named fws_PORTAL exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_ALL_INTERNAL --set .COMMENT 'FWShift: ALL_INTERNAL'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_SERVERS --set .COMMENT 'FWShift: SERVERS'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_WAN_to_Web_dst --set .COMMENT 'FWShift: WEB_SRV, PUBLIC_WEB'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.10
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_WAN_to_Mail_dst --set .COMMENT 'FWShift: MAIL_SRV, 198.51.100.11'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.11
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_ADMIN_PCS --set .COMMENT 'FWShift: ADMIN_PCS'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.50-10.10.0.59
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_PORTAL --set .COMMENT 'FWShift: PORTAL'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP portal.example.com
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_WEB --set .COMMENT 'FWShift: WEB'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080-8089
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_MGMT --set .COMMENT 'FWShift: MGMT'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 22
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080-8089
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'LAN1_Outgoing: LAN1 to the internet'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_ALL_INTERNAL
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT 1024:65535 --set .IN_IP 0.0.0.0/0 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT DNS_From_Port
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT Portal_Access
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_PORTAL
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 203.0.113.0/25 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF DROP --set .LOG yes --set .COMMENT Block_Partner_SSH
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_SERVERS
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT WAN_to_Web
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_WAN_to_Web_dst
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_WEB
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT WAN_to_Mail
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_WAN_to_Mail_dst
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT Admin_Mgmt
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_ADMIN_PCS
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_SERVERS
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_MGMT
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT LAN1_to_DMZ_Reject
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 10.30.0.30 --set .REMOTE_NET 198.51.100.30 --set .MASK 32 --set .ENABLE_ARP yes --set .COMMENT 'virtual-server ONE2ONE: ip virtual-server ONE2ONE interface ge1 original-ip 198.51.100.30 map-to 10.30.0.30 map-type any'
N=$((N+1))
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 10.30.0.20 --set .REMOTE_NET 198.51.100.20 --set .MASK 30 --set .ENABLE_ARP yes --set .COMMENT 'virtual-server MANY2ONE: ip virtual-server MANY2ONE interface ge1 original-ip PUBLIC_RANGE map-to INSIDE_RANGE map-type'
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 10.10.0.0/24 --set .COMMENT 'policy-route 2: LAN1 out with the WAN address'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
